package com.mamtrex.hospital.inventory;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/inventory-items") public class InventoryItemController { private final InventoryItemRepository repo; private final AuditService audit; public InventoryItemController(InventoryItemRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String sku, @jakarta.validation.constraints.NotBlank String name, @jakarta.validation.constraints.NotBlank String category, @jakarta.validation.constraints.NotBlank String quantity, @jakarta.validation.constraints.NotBlank String reorderLevel){} @PostMapping public InventoryItem create(@Valid @RequestBody Request r){var e=repo.save(new InventoryItem(r.sku(), r.name(), r.category(), r.quantity(), r.reorderLevel()));audit.record("CREATE","InventoryItem",e.getId().toString(),"created");return e;} @GetMapping public List<InventoryItem> list(){return repo.findAll();} @GetMapping("/{id}") public InventoryItem get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("InventoryItem not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("InventoryItem not found: "+id);repo.deleteById(id);audit.record("DELETE","InventoryItem",id.toString(),"deleted");} }
